      slug: external_exports.string().min(1).max(80).optional().describe("Kurz-URL; wird zu Kleinbuchstaben/Bindestrichen normalisiert"),
      tagline: external_exports.string().max(200).optional(),
      description: external_exports.string().max(4e3).optional(),
      org_type: external_exports.enum(ORG_KEYS).optional(),
      visibility: external_exports.enum(["private", "workspace"]).optional().describe("workspace = alle Workspace-Mitglieder d\xFCrfen ansehen, private = nur Eingeladene"),
      theme: themeShape.optional(),
