// mcp/src/tools/workspaces.ts
var WORKSPACE_ROLES = ["owner", "admin", "member"];
var workspaceTools = [
  defineTool({
    name: "create_workspace",
    title: "Workspace anlegen",
    description: "Legt einen neuen Workspace an (z. B. einen Kurs oder ein Team). Du wirst Owner. Der Workspace geh\xF6rt automatisch zur Freigabe dieser Verbindung.",
    input: {
      name: external_exports.string().min(1).max(120),
      description: external_exports.string().max(1e3).optional()
    },
    kind: "write",
    async run({ name, description }, ctx) {
      await ctx.assertWriteAllowed();
      const ws = row(
        await ctx.sb.rpc("create_workspace", { p_name: name.trim(), p_description: description ?? "" })
      );
      ctx.invalidateScope();
      return {
        summary: `Workspace \u201E${ws.name}\u201C angelegt.`,
        data: { id: ws.id, name: ws.name, slug: ws.slug, url: ctx.link(`/w/${ws.slug}`) }
      };
    }
  }),
  defineTool({
    name: "update_workspace",
    title: "Workspace bearbeiten",
    description: "\xC4ndert Name oder Beschreibung eines Workspaces (Rolle Owner oder Admin).",
    input: {
      workspace: external_exports.string().optional().describe("Workspace (Name, Kurz-URL oder ID)"),
      name: external_exports.string().min(1).max(120).optional(),
      description: external_exports.string().max(1e3).optional()
    },
    kind: "write",
    idempotent: true,
    async run({ workspace: ref, name, description }, ctx) {
      const ws = await ctx.adminWorkspace(ref);
      const patch = defined({ name: name?.trim(), description });
      requireChange(patch);
      const [updated] = affected(
        await ctx.sb.from("workspaces").update(patch).eq("id", ws.id).select("id, name, slug, description"),
        "Workspace"
      );
      ctx.invalidateScope();
      return { summary: `Workspace \u201E${updated.name}\u201C gespeichert.`, data: updated };
    }
  }),
  defineTool({
    name: "delete_workspace",
    title: "Workspace l\xF6schen",
    description: "L\xF6scht einen Workspace samt ALLER Marken, Texte und Dateien darin. Unwiderruflich. Nur Owner. Zur Sicherheit muss der Name des Workspaces exakt als confirm_name wiederholt werden.",
    input: {
      workspace: external_exports.string().describe("Workspace (Name, Kurz-URL oder ID)"),
      confirm_name: external_exports.string().describe("Exakter Name des Workspaces zur Best\xE4tigung")
    },
    kind: "destructive",
    async run({ workspace: ref, confirm_name }, ctx) {
      const ws = await ctx.ownerWorkspace(ref);
      if (confirm_name.trim() !== ws.name) {
        throw new ToolError(`Zur Best\xE4tigung muss confirm_name genau \u201E${ws.name}\u201C lauten.`);
      }
      const brands = rows(await ctx.sb.from("brands").select("id").eq("workspace_id", ws.id));
      for (const brand of brands) await removeBrandFiles(ctx, brand.id);
      affected(await ctx.sb.from("workspaces").delete().eq("id", ws.id).select("id"), "Workspace");
      ctx.invalidateScope();
      return { summary: `Workspace \u201E${ws.name}\u201C mit ${brands.length} Marke(n) gel\xF6scht.` };
    }
  }),
  defineTool({
    name: "list_workspace_members",
    title: "Workspace-Mitglieder",
    description: "Listet die Mitglieder eines Workspaces mit Rollen (owner, admin, member).",
    input: { workspace: external_exports.string().optional() },
    kind: "read",
    async run({ workspace: ref }, ctx) {
      const ws = await ctx.workspace(ref);
      const data = rows(
        await ctx.sb.from("workspace_members").select("user_id, role, created_at, profile:profiles(full_name, email)").eq("workspace_id", ws.id).order("created_at")
      );
      return {
        summary: `${data.length} Mitglied(er) in \u201E${ws.name}\u201C.`,
        data: data.map((m) => ({
          user_id: m.user_id,
          name: m.profile?.full_name ?? null,
          email: m.profile?.email ?? null,
          role: m.role,
          since: m.created_at
        }))
      };
    }
  }),
  defineTool({
    name: "set_workspace_member_role",
    title: "Workspace-Rolle \xE4ndern",
    description: "\xC4ndert die Rolle eines Workspace-Mitglieds (owner, admin, member). Owner-Rechte vergeben oder entziehen d\xFCrfen nur Owner; ein Workspace beh\xE4lt immer mindestens einen Owner.",
    input: {
      workspace: external_exports.string().optional(),
      user: external_exports.string().describe("E-Mail-Adresse oder user_id des Mitglieds"),
      role: external_exports.enum(WORKSPACE_ROLES)
    },
    kind: "write",
    idempotent: true,
    async run({ workspace: ref, user: user2, role }, ctx) {
      const ws = await ctx.adminWorkspace(ref);
      const member = await findWorkspaceMember(ctx, ws.id, user2);
      affected(
        await ctx.sb.from("workspace_members").update({ role }).eq("workspace_id", ws.id).eq("user_id", member.user_id).select("user_id"),
        "Mitglied"
      );
      return { summary: `${member.email ?? member.user_id} ist jetzt ${role} in \u201E${ws.name}\u201C.` };
    }
  }),
  defineTool({
    name: "remove_workspace_member",
    title: "Mitglied aus Workspace entfernen",
    description: "Entfernt eine Person aus einem Workspace (Rolle Owner oder Admin). Der letzte Owner kann nicht entfernt werden.",
    input: { workspace: external_exports.string().optional(), user: external_exports.string().describe("E-Mail-Adresse oder user_id") },
    kind: "destructive",
    async run({ workspace: ref, user: user2 }, ctx) {
      const ws = await ctx.adminWorkspace(ref);
      const member = await findWorkspaceMember(ctx, ws.id, user2);
      affected(
        await ctx.sb.from("workspace_members").delete().eq("workspace_id", ws.id).eq("user_id", member.user_id).select("user_id"),
        "Mitglied"
      );
      return { summary: `${member.email ?? member.user_id} wurde aus \u201E${ws.name}\u201C entfernt.` };
    }
  })
];
async function findWorkspaceMember(ctx, workspaceId, ref) {
  const members2 = rows(
    await ctx.sb.from("workspace_members").select("user_id, profile:profiles(email, full_name)").eq("workspace_id", workspaceId)
  );
  const needle = ref.trim().toLowerCase();
  const found = members2.find((m) => m.user_id === ref || m.profile?.email?.toLowerCase() === needle);
  if (!found)
    throw new ToolError(
      `Mitglied \u201E${ref}\u201C nicht gefunden.`,
      "Nimm die E-Mail-Adresse aus list_workspace_members."
    );
  return { user_id: found.user_id, email: found.profile?.email ?? null };
}

// mcp/src/server.ts
var ALL_TOOLS = [
  ...overviewTools,
  ...workspaceTools,
  ...brandTools,
  ...memberTools,
  ...guidelineTools,
  ...basicsTools,
  ...libraryTools,
  ...collabTools
];
function buildServer(ctx) {
  const server = new McpServer(
    { name: SERVER_NAME, title: "Brandbench", version: SERVER_VERSION },
    { instructions: SERVER_INSTRUCTIONS, capabilities: { tools: {}, prompts: {} } }
  );
  registerTools(server, ctx, ALL_TOOLS);
  registerPrompts(server);
  return server;
}

